UPDATE screening
SET available_tickets = available_tickets - #{quantity},
    sold_tickets = sold_tickets + #{quantity},
    version = version + 1,
    update_time = #{updateTime}
WHERE id = #{screeningId}
  AND deleted = 0
  AND available_tickets >= #{quantity}

